using static StrataLint.Scribe.DefinitionDsl;

namespace StrataLint.Scribe.Blueprint.D5.S3.FiniteGroups.NikolovSegal;

internal sealed class GeneratorDecompositionDocument : IScribeDocumentDefinition
{
    private static readonly LibraryNoteRef Source = LibraryNoteRef.Create("D5/L/FiniteGroups/nikolov2011powers");

    public DocumentDefinition Create() => DocumentDefinition.Create(ScribeNode.Create(
        "Finite-order induction gives the generator decomposition with a fixed exact power-product length under a uniform minimal-normal absorption premise.",
        H("Generator decomposition under explicit absorption"),
        Blocks(
            Describe.Lean(
                DescribeId.Create("nikolov-segal-generatordecomposition-large-minimal-normal-absorption"),
                DeclarationHandle.Create("D5/S3/FiniteGroups/NikolovSegal/GeneratorDecomposition.LargeMinimalNormalAbsorption"),
                H("The unproved large minimal-normal input"), StatementSource.WithoutFormula(),
                AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("Fix natural q, m and k before quantifying over all finite groups G in an arbitrary universe. For every subgroup N minimal among nontrivial normal subgroups, if alpha(N) is greater than k, then every a in N and every x in orderedPowerProducts(G,q,m) satisfy a*x in that same set. Absorption acts on the left and preserves the same exact m ordered qth-power factors. This proposition is an explicit input, with no supplied proof. In the paper the corresponding input follows from Proposition 2 and the classification of minimal normal subgroups."))),
                DescribeRole.Definition),
            Describe.Lean(
                DescribeId.Create("nikolov-segal-generatordecomposition-generator-decomposition-of-absorption"),
                DeclarationHandle.Create("D5/S3/FiniteGroups/NikolovSegal/GeneratorDecomposition.generator_decomposition_of_absorption"),
                H("Complete induction for every finite group"), StatementSource.WithoutFormula(),
                AssessedProvenance.FromLiterature(Source),
                Blocks(Paragraph(Text("For all natural q, m and k with k at least four, assuming LargeMinimalNormalAbsorption(q,m,k) uniformly over finite groups with m already fixed, every finite group G and natural d with Group.rank(G) at most d admit tuples x and y from Fin d to G. The closure of the union of their ranges is G; every x(i) is a product of the same exact m ordered qth powers; and alpha of the subgroup generated by y is at most k. This includes d equal to zero and arbitrary finite groups, with no solvability or commutativity assumption."))),
                DescribeRole.Theorem),
            Paragraph(Text("Induct on the finite order of G. For a minimal nontrivial normal subgroup N, the quotient has strictly smaller order and rank at most d. Lift the x factors in order, and lift y using the same Lemma 2 supplement. If alpha(N) is at most k, apply Gaschutz with x fixed and correct y; the corrected subgroup lies in the bounded preimage. Otherwise apply Gaschutz with y fixed and correct x; left absorption preserves every exact power-product constraint.")),
            Paragraph(Text("Taking the finite images of the two tuples gives sets X and Y of cardinality at most d with the same generation, power-product and alpha conclusions. The paper proves an unconditional Proposition 3 by supplying the absorption input. Here that input remains unproved. Uniform power width, Proposition 4, the restricted Burnside bound and strong completeness remain outside this conditional induction.")))));
}
